from pathlib import Path
import os,json,subprocess,statistics,time,hashlib
from tools.sloppy_core.benchmark_apps import prepare_source
root=Path('__dewycache__/task-tmp/map-slot-key').resolve()
compilers={k:Path(f'__dewycache__/compact-core/build-{v}/bin/dewy-core').resolve() for k,v in [('baseline','1792328534421336799'),('candidate','1792329233769503272')]}
env={k:v for k,v in os.environ.items() if not k.startswith(('DEWY_','SLOPPY_'))};env['SLOPPY_EMIT_WORKERS']='1'
source=prepare_source('graph',root)
for label,compiler in compilers.items(): subprocess.run([compiler,'build',source,'--release','-o',root/label],env=env,check=True,capture_output=True)
def sample(command,output):
    start=time.monotonic();pid=os.fork()
    if pid==0:
        fd=os.open(output,os.O_WRONLY|os.O_CREAT|os.O_TRUNC,0o600)
        os.dup2(fd,1);os.dup2(fd,2);os.close(fd)
        os.execve(str(command[0]),[str(x) for x in command],env)
    _,status,usage=os.wait4(pid,0)
    assert status==0,(command,status,output.read_text())
    return {'peak_rss_kib':usage.ru_maxrss,'cpu_seconds':usage.ru_utime+usage.ru_stime,'wall_seconds':time.monotonic()-start,'stdout':output.read_text()}
results={}
for workload in ['graph','compiler']:
    rows={k:[] for k in compilers}
    for i in range(3):
        for label in (list(compilers) if i%2==0 else list(compilers)[::-1]):
            command=[root/label,'1000000'] if workload=='graph' else [compilers[label],'build',Path('core/compiler/main.jo').resolve(),'-o',root/f'self-{label}']
            rows[label].append(sample(command,root/f'{workload}-{label}-{i}.out'))
    results[workload]={'samples':rows,'median_peak_rss_kib':{k:statistics.median(r['peak_rss_kib'] for r in v) for k,v in rows.items()}}
    print(workload,results[workload]['median_peak_rss_kib'],flush=True)
results['limits']=['Linux wait4 peak resident memory for the whole child process, including setup and cleanup.', 'Three alternating samples, CPU 2. Compiler source is the same candidate working tree for both compilers.']
results['compilers']={k:{'path':str(v),'sha256':hashlib.sha256(v.read_bytes()).hexdigest()} for k,v in compilers.items()}
(root/'memory.json').write_text(json.dumps(results,indent=2)+'\n')
